create table if not exists policy(id int primary key, weekdays varchar(7) not null, opens time not null, closes time not null, cutoff time not null);
create table if not exists closure(id bigint generated by default as identity primary key, starts date not null, ends date not null, reason varchar(180) not null);
create table if not exists item(id bigint primary key, title varchar(80) not null, next_day boolean not null);
create table if not exists unit(id bigint generated by default as identity primary key, item_id bigint not null references item, code varchar(32) unique not null, state varchar(12) not null check(state in ('AVAILABLE','OUT','DISABLED')));
create table if not exists staff(id bigint primary key, name varchar(50) unique not null, phone varchar(20) not null);
create table if not exists borrower(student_no varchar(8) primary key, late_count int not null default 0, suspended boolean not null default false);
create table if not exists application(id bigint generated by default as identity primary key, token varchar(40) unique not null, student_no varchar(8) not null references borrower, name varchar(50) not null, phone varchar(20) not null, faculty varchar(64) not null, department varchar(64) not null, item_id bigint not null references item, created timestamp not null, state varchar(16) not null);
create table if not exists loan(id bigint generated by default as identity primary key, request_id bigint unique not null references application, staff_id bigint not null references staff, issued timestamp not null, due timestamp not null, returned timestamp, late boolean not null default false, deposit_received boolean not null, card_received boolean not null, deposit_back boolean not null default false, card_back boolean not null default false, memo varchar(500) not null);
create table if not exists allocation(loan_id bigint not null references loan, unit_id bigint not null references unit, primary key(loan_id,unit_id));
create table if not exists audit(id bigint generated by default as identity primary key, happened timestamp not null, actor varchar(50) not null, detail varchar(600) not null);

create table if not exists staff_login(staff_id bigint primary key references staff, username varchar(50) unique not null,password_hash varchar(120) not null);

alter table loan add column if not exists exception_reason varchar(180);

create table if not exists item_photo(item_id bigint primary key references item, image_bytes blob not null, revision varchar(36) not null);
alter table application add column if not exists consent_at timestamp;

create table if not exists retired_item(item_id bigint primary key references item);

alter table staff add column if not exists archived_name varchar(50);
alter table staff_login add column if not exists session_key uuid default random_uuid() not null;
create table if not exists duty_source(id int primary key, sheet_id varchar(128) not null);
